// Get the input data (usually one item containing all lists)
const inputData = $input.item.json;

// Extract the 'lists' array from the API response
const lists = inputData.lists;

// Filter out lists that are hidden
const visibleLists = lists.filter(list => list.folder.hidden !== true);

// Get the count of visible lists
const listCount = visibleLists.length;

// Create output items
const result = [];

for (const list of visibleLists) {
  result.push({
    json: {
      ...list,
      myNewField: 1,
      totalLists: listCount
    }
  });
}

return result;

