// Lấy toàn bộ dữ liệu đầu vào
const items = $input.all();

// Hàm kiểm tra định dạng URL
const isYoutubeUrl = (url) => url.includes('youtube.com') || url.includes('youtu.be');
const isOneDriveUrl = (url) => url.includes('onedrive') || url.includes('1drv.ms');

// Hàm trích xuất URL từ chuỗi comment_text
const extractUrlFromText = (text) => {
  if (!text) return null;
  const ignoredPattern = /Attachment ignored:\s*(https?:\/\/[^\s]+)/;
  const match = text.match(ignoredPattern);
  if (match) return match[1];

  const genericPattern = /(https?:\/\/[^\s]+)/;
  const matchGeneric = text.match(genericPattern);
  return matchGeneric ? matchGeneric[1] : null;
};

// Kết quả được lưu theo taskId
const resultMap = new Map();

// Duyệt qua từng item
for (const item of items) {
  const taskId = item.json?.task?.id;
  if (!taskId) continue;

  // Nếu chưa có taskId trong resultMap thì khởi tạo
  if (!resultMap.has(taskId)) {
    resultMap.set(taskId, {
      json: {
        id: taskId,
        youtube_link: [],
        onedrive_link: [],
        other_link: [],
      }
    });
  }

  const result = resultMap.get(taskId);
  let foundUrls = [];

  // 1. Lấy từ comment[].bookmark.url nếu có
  const comments = item.json.comment || [];
  for (const c of comments) {
    const url = c?.bookmark?.url;
    if (url) {
      foundUrls.push(url);
    }
  }

  // 2. Nếu chưa có URL, thử lấy từ comment_text
  if (foundUrls.length === 0 && item.json.comment_text) {
    const extractedUrl = extractUrlFromText(item.json.comment_text);
    if (extractedUrl) {
      foundUrls.push(extractedUrl);
    }
  }

  // 3. Phân loại và lưu vào object
  for (const url of foundUrls) {
    if (isYoutubeUrl(url)) {
      result.json.youtube_link.push(url);
    } else if (isOneDriveUrl(url)) {
      result.json.onedrive_link.push(url);
    } else {
      result.json.other_link.push(url);
    }
  }
}

// Trả kết quả về dạng array
return Array.from(resultMap.values());

