const input = $('task_start').first().json || {};
const historyItems = input.history_items || [];
const taskId = input.task_id || 'Không xác định';

const task = $('cr_task_merge').first().json || {};

// Hàm làm sạch
const clean = val => typeof val === 'string' ? val.trim() || '—' : (val ?? '—');

// 🔄 Các thay đổi
const changes = historyItems.map(h => {
  const field = h.custom_field?.name || h.field || 'Trường không xác định';
  const user = h.user?.username || 'Không rõ';

  const formatVal = val => {
    if (val === null || val === undefined) return '—';
    if (Array.isArray(val)) return val.join(', ');
    return val.toString();
  };

  const before = formatVal(h.before);
  const after = formatVal(h.after);

  return `📝 Trường "${field}" được cập nhật bởi ${user}\n• `;
}).join('\n\n') || '— Không có thay đổi —';


// 🧾 Task info
const taskInfo = `
🆔 ID: ${clean(task.id)}
📌 Tên: ${clean(task.name)}
🔗 Link: ${clean(task.url)}
📊 Trạng thái: ${clean(task.status)}

`;

// Final message
const message = `
🔄 Thông báo cập nhật Task

🔧 Các thay đổi:
${changes}

📦 Thông tin chi tiết:
${taskInfo.trim()}

🕒 Cập nhật lúc: ${new Date().toLocaleString()}
`;

return [{
  json: {
    message: message.trim()
  }
}];

