function removeVietnameseTones(str) {
  return str.normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/đ/g, "d")
            .replace(/Đ/g, "D");
}

// Xử lý từng item
const output = inputItems.map(item => {
  const name = item.json.name || '';
  const name_khong_dau = removeVietnameseTones(name);

  return {
    json: {
      ...item.json,
      name_khong_dau
    }
  };
});

return output;

