CREATE SCHEMA IF NOT EXISTS clickup;

CREATE TABLE IF NOT EXISTS clickup.db_config (
  id BIGSERIAL PRIMARY KEY,
  config_key VARCHAR(100) UNIQUE,
  config_value TEXT,
  description TEXT,
  date_created TIMESTAMPTZ DEFAULT now(),
  date_modified TIMESTAMPTZ DEFAULT now()
);

-- trigger tự động cập nhật date_modified khi UPDATE
CREATE OR REPLACE FUNCTION clickup_set_updated_at() RETURNS trigger AS $$
BEGIN NEW.date_modified = now(); RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_db_config_updated ON clickup.db_config;
CREATE TRIGGER trg_db_config_updated
BEFORE UPDATE ON clickup.db_config
FOR EACH ROW EXECUTE FUNCTION clickup_set_updated_at();

